package com.easyperformance.program;
import com.easyperformance.program.ProgramTypes.GoalStatus;import com.easyware.platform.UuidV7;import com.easyware.platform.audit.TenantAwareAuditEntity;import jakarta.persistence.*;import org.hibernate.annotations.Immutable;import java.util.UUID;
@Entity @Immutable @Table(name="program_goal_event",indexes=@Index(name="ix_program_goal_event_tenant_goal",columnList="tenant_id, goal_id, revision"))
public class ProgramGoalEvent extends TenantAwareAuditEntity{
 @Id @Column(columnDefinition="uuid",nullable=false,updatable=false)private UUID id;@Column(name="goal_id",columnDefinition="uuid",nullable=false,updatable=false)private UUID goalId;@Column(nullable=false,updatable=false)private int revision;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30,updatable=false)private GoalStatus status;@Column(nullable=false,length=40,updatable=false)private String operation;@Column(columnDefinition="text",updatable=false)private String opinion;@Column(name="actor_employee_id",columnDefinition="uuid",updatable=false)private UUID actorEmployeeId;
 @PrePersist void prePersist(){if(id==null)id=UuidV7.generate();}public UUID getId(){return id;}public void setId(UUID v){id=v;}public UUID getGoalId(){return goalId;}public void setGoalId(UUID v){goalId=v;}public int getRevision(){return revision;}public void setRevision(int v){revision=v;}public GoalStatus getStatus(){return status;}public void setStatus(GoalStatus v){status=v;}public String getOperation(){return operation;}public void setOperation(String v){operation=v;}public String getOpinion(){return opinion;}public void setOpinion(String v){opinion=v;}public UUID getActorEmployeeId(){return actorEmployeeId;}public void setActorEmployeeId(UUID v){actorEmployeeId=v;}
}
